-- Chat (RFC: Chat (v2), Step 65). Additive only: new, empty tables and a wider check, nothing v1 reads.
-- Channels are made by Go when first listed, so no rows are written here.

-- Chat is its own app: member or admin, as seller and backoffice have theirs.
ALTER TABLE public.user_app_access DROP CONSTRAINT user_app_access_check;
ALTER TABLE public.user_app_access ADD CONSTRAINT user_app_access_check CHECK (
    (app = 'seller' AND access = 'member')
    OR (app = 'backoffice' AND access IN ('guest', 'admin'))
    OR (app = 'chat' AND access IN ('member', 'admin'))
);

CREATE TABLE public.chat_channels (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL REFERENCES public.tenants (id) ON DELETE CASCADE,
    kind text NOT NULL CHECK (kind IN ('general', 'store', 'group', 'admin', 'personal')),
    store_id uuid REFERENCES public.stores (id),
    user_id uuid REFERENCES public.users (id),
    -- A group's only; the others show their store's name or a translated label.
    name text,
    created_by uuid REFERENCES public.users (id),
    -- Written with each message, so listing channels needs no scan of their messages.
    last_message_id uuid,
    last_message_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK ((kind = 'store') = (store_id IS NOT NULL)),
    CHECK ((kind = 'personal') = (user_id IS NOT NULL))
);
-- One of each per tenant, store or person: making one twice does nothing.
CREATE UNIQUE INDEX chat_channels_general ON public.chat_channels (tenant_id) WHERE kind = 'general';
CREATE UNIQUE INDEX chat_channels_admin ON public.chat_channels (tenant_id) WHERE kind = 'admin';
CREATE UNIQUE INDEX chat_channels_store ON public.chat_channels (store_id) WHERE kind = 'store';
CREATE UNIQUE INDEX chat_channels_personal ON public.chat_channels (tenant_id, user_id) WHERE kind = 'personal';

CREATE TABLE public.chat_messages (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL REFERENCES public.tenants (id) ON DELETE CASCADE,
    channel_id uuid NOT NULL REFERENCES public.chat_channels (id),
    -- Flat threads: a reply points at its root, never at another reply.
    thread_root_id uuid REFERENCES public.chat_messages (id),
    author_type text NOT NULL CHECK (author_type IN ('user', 'system')),
    author_id uuid REFERENCES public.users (id),
    -- System messages only: what happened, written in each reader's language by the phone.
    event_type text,
    body text NOT NULL DEFAULT '' CHECK (char_length(body) <= 4000),
    metadata jsonb NOT NULL DEFAULT '{}',
    -- The phone's Idempotency-Key: matches its own copy to this one, and stops a double post.
    client_key text,
    edited_at timestamptz,
    deleted_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK ((author_type = 'user') = (author_id IS NOT NULL))
);
CREATE INDEX chat_messages_channel ON public.chat_messages (channel_id, created_at DESC, id DESC);
CREATE INDEX chat_messages_thread ON public.chat_messages (thread_root_id, created_at) WHERE thread_root_id IS NOT NULL;
CREATE UNIQUE INDEX chat_messages_client_key ON public.chat_messages (author_id, client_key) WHERE client_key IS NOT NULL;

-- A message's photos (Step 67): the 1080 px copy and its 320 px preview, in a private bucket.
CREATE TABLE public.chat_message_photos (
    message_id uuid NOT NULL REFERENCES public.chat_messages (id),
    position smallint NOT NULL CHECK (position BETWEEN 0 AND 3),
    path text NOT NULL,
    preview_path text NOT NULL,
    width int NOT NULL,
    height int NOT NULL,
    PRIMARY KEY (message_id, position)
);

-- Per person and channel: how far they have read, how much they are told. For a chat admin outside
-- a channel, the row is also their follow (Step 70).
CREATE TABLE public.chat_reads (
    user_id uuid NOT NULL REFERENCES public.users (id),
    channel_id uuid NOT NULL REFERENCES public.chat_channels (id),
    last_read_at timestamptz NOT NULL DEFAULT '-infinity',
    notify_level text NOT NULL DEFAULT 'all' CHECK (notify_level IN ('all', 'humans', 'none')),
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, channel_id)
);
CREATE INDEX chat_reads_channel ON public.chat_reads (channel_id);

-- A phone's push subscription (Step 68), upserted by its endpoint on every start: the row is
-- the real off switch. Push is not only chat's.
CREATE TABLE public.push_subscriptions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES public.users (id),
    endpoint text NOT NULL UNIQUE,
    p256dh text NOT NULL,
    auth text NOT NULL,
    user_agent text NOT NULL DEFAULT '',
    created_at timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX push_subscriptions_user ON public.push_subscriptions (user_id);

-- Go is the only way in: v1's browser carries the Supabase key, and these must not be readable through it.
ALTER TABLE public.chat_channels ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.chat_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.chat_reads ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.chat_message_photos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.push_subscriptions ENABLE ROW LEVEL SECURITY;

